SELECT CASE WHEN products.cost >= 570 THEN 'high' WHEN products.cost >= 310 THEN 'mid' ELSE 'low' END cost_bucket, COUNT(*) total_count FROM store_sales INNER JOIN stores ON store_sales.store_id = stores.id LEFT JOIN products ON store_sales.product_id = products.id GROUP BY CASE WHEN products.cost >= 570 THEN 'high' WHEN products.cost >= 310 THEN 'mid' ELSE 'low' END ORDER BY total_count;
